ERIS_OWNER = 'terra1kefa2zgjn45ctj32d3tje5jdwus7px6n2klgzl'
PF_BOARD = 'terra1k8ug6dkzntczfzn76wsh24tdjmx944yj6mk063wum7n20cwd7lxq4lppjg'
TREASURY_ADDRESS = 'terra16st8yfprkdl06kccktshd3p2vccq93xcn9mkhjl8s4jumyjtd4kqye0me5'
DOCS_PIN = 'https://github.com/phoenix-directive/docs/blob/7cebbd26048f0e1568a2aed55177090b90788d8b/common_backup/'
