control_rows = [[e(r['label']), '<code>'+e(r['address'])+'</code>', e(r['code_id']), e(control_identity(r.get('admin'))), contract_record(r['name'],'Contract record')] for r in control_inventory]
control_balances = json.loads((control_source / 'chain/treasury-bank-balances.json').read_text())['balances']
