infrastructure_grants = [
    [control_link('approvals/native-4813.json','Terra #4813 · passed'), '384,615 LUNA; described as $200,000 development plus $50,000 audit for TLA.', 'ERIS is the implementation partner. The development text describes acquired liquidity positions as Community Pool protocol-owned liquidity.'],
    [control_link('approvals/native-4816.json','Terra #4816 · passed'), '243,902 LUNA; described as $100,000 for Phoenix setup: $60,000 legal framework and $40,000 infrastructure/Treasury development, audit and buffer.', 'Public-good funding, not a transfer of Treasury assets to ERIS. The full award must not be described as an ERIS payment.'],
    [control_link('approvals/native-4817.json','Terra #4817 · passed'), 'TLA launch and Alliance assets; proposal links the detailed launch terms.', 'Linked terms give ERIS temporary upgrade/configuration roles and promise transfer to Stewardship after one/three months.'],
    [control_link('approvals/native-4822.json','Terra #4822 · passed'), 'Treasury launch: 14% Alliance reward weight, described as 10% of chain staking rewards.', 'Linked terms promise audited open-source Treasury, vetoes, governance defunding and clawback. They do not independently state the TLA handover deadlines.'],
]
application_grants = [
    [control_link('approvals/board-A107.json','Board A107 · executed'), '50,000 USDC Votion award in two milestones.', 'Application-development award. The funding message contains no express software-IP assignment or TLA-style administrator handover term.'],
    [control_link('approvals/board-A190.json','Board A190 · executed'), '210,000-USDC Creda award: 40k kickoff, 100k mainnet, 60k eMode/isolation, 10k analytics.', 'A209/A215 enabled these milestones; they were not new awards or transfers of contract administration. Claimed status is not independent acceptance of every deliverable.'],
    [control_link('approvals/board-A266.json','Board A266 · executed'), '125,000-USDC Estima award: 45k kickoff, 45k mainnet, 35k analytics/TLA integration.', 'Other directors approved the original grant without a recorded 0xPhilipp vote. A271 enabled 45k; the retained payment record establishes 45k paid, not payment of the remaining 80k.'],
]
legacy_grants = [
    [control_link('approvals/native-3796.json','Terra #3796 · passed'), '312,500 LUNA; described as $500,000 for ERIS development, audits and operations, with staged release.', 'The linked revised grant promises 10% of ERIS revenues across Terra and feather chains to the community pool; if ERIS introduces a revenue-capturing token, it permits replacement with a 10% total-supply airdrop. It does not establish community ownership of all ERIS IP or ERIS ownership of user deposits.'],
]

control = head('TLA and Treasury: who controls the funds?', 'Approved infrastructure funding, delivered safeguards and the control handovers that remain incomplete.') + f'''<div class="wrap page-content">
<section id="findings"><p class="note">Checked 16 November 2026. This review follows 27 named Terra contracts and selected approved proposals. It is a bounded control map, not a complete inventory of ERIS property or an audit of every transaction.</p><div class="section-heading"><h2>The central concern is control of TLA and Treasury</h2><p>These systems were funded to manage chain liquidity and community funds. ERIS delivered deployed infrastructure and the Board holds meaningful operating powers, but ERIS-associated addresses retain migration administration and registry ownership. TLA’s published one-month and three-month handover commitments remain incomplete.</p></div><div class="two-col"><article><h3>A documented commitment remains incomplete</h3><p>The TLA launch terms promised migration-admin transfer to Phoenix Stewardship after one month and configuration ownership after three. The named ERIS addresses still hold those roles across the reviewed TLA deployment. No approved extension was identified in the reviewed records.</p></article><article><h3>Some control has transferred</h3><p>ERIS proposal 9 transferred upgrade administration of the ampLUNA hub and CW20-ICS20 bridge to the Board on 25 October 2026. Their internal permissions remain separate. The Board has since exercised its upgrade authority through A292.</p></article></div><p><strong>Application grants are a separate question.</strong> Creda, Votion and Estima funded applications; the grants alone do not establish community ownership of their software or an obligation to surrender administration. They are <a href="#application-grants">listed separately</a> and are not the basis for the TLA/Treasury handover finding.</p><p>These keys are not beyond native Terra governance: an approved executable proposal can reassign administrators or migrate contracts. <a href="#governance-remedies">The available remedies have different effects and limits.</a></p><p><a href="#treasury-contract">What the Treasury administrator could do</a> · <a href="#inventory">Contract map</a> · <a href="#approvals">What governance authorized</a> · <a href="#handover">Promises and completed transfers</a></p>{source_list([(TLA_TERMS+'#L144-L169','TLA launch: separate roles and transfer promises'),(CONTROL+'chain/tla-registry-ownership.json','Current registry ownership'),(CONTROL+'handover/eris-proposals.json','P9 executed messages'),(CONTROL+'handover/A292.json','A292 executed Board upgrade')])}</section>
<section id="ownership"><div class="section-heading"><h2>Control is not legal ownership</h2></div>{table(['Question','What the record establishes'],[
['Who owns the assets?', 'The TLA development text describes acquired LP positions as Community Pool liquidity. User deposits and the tokens representing them remain subject to their protocol claims. A grant is funding for an agreed scope; balances, fees and technical permissions do not establish beneficial ownership or personal profit.'],
['Who can replace a contract?', 'Its migration administrator can authorize new code, subject to chain rules. This is a separate layer from ordinary spending approval.'],
['Who can change settings?', 'An internal owner or registry role controls the functions assigned to it by the deployed code. A field named owner is not a legal title deed.'],
['Who can operate it?', 'Controllers, voting operators, whitelist managers and executors have distinct permissions. Paying for development or operating a service does not by itself settle the permanent authority to govern it.']])}<p>Software licences, IP assignments, grant conditions and any later approved variations need their own register. This review did not establish legal title to every ERIS product or find an approved blanket entitlement to retain all community-system powers indefinitely.</p></section>
<section id="treasury-contract"><div class="section-heading"><h2>The Treasury has more than one control layer</h2><p><code>{TREASURY_ADDRESS}</code> is labelled <strong>phoenix_treasury</strong>, code 3347. It manages Alliance-funded Treasury activity, including payments and grants, vesting/milestones, DCA/OTC operations and reward/delegation activity.</p></div>{table(['Layer','Observed authority','Why it matters'],[
['Ordinary spending controller', 'Phoenix Board: registry PDT_CONTROLLER. Current proposal threshold is 75%; four equal members means three YES votes.', 'Collective approval exists for the normal route. It is inaccurate to describe all Treasury payments as unilateral ERIS actions.'],
['Upgrade administrator', '<code>'+ERIS_ADMIN+'</code> — identified as ERIS in the launch terms.', 'Can authorize replacement code for this contract. The current spending and veto code is not an immutable restriction on the upgrade administrator.'],
['Registry/configuration authority', '<code>'+ERIS_OWNER+'</code> owns the shared registry and is PDT_CONFIG_OWNER. No pending registry owner is recorded.', 'The registry determines role addresses. Retained transactions demonstrate this address setting PDT_CONFIG_OWNER and FEE_COLLECTOR. Exact present setter limits need deployed-source review.'],
['Configured vetoes / published clawback promise', 'The veto-owner address is Terra’s governance module. Configuration records Think Tank thresholds of $50k per action / $150k over 30 days with a three-day delay; governance $150k / $450k with ten days, plus a zero-threshold governance entry.', 'These are real recorded safeguards and published governance protections. Their implementation and upgrade resistance are separate questions.'],
['DCA execution', 'PDT_DCA_EXECUTOR lists the Board and a second address ending c5vlup.', 'An executor role is not proof of permission to create arbitrary payments or ownership of the funds. The second address is not attributed here.']])}
<p>At capture, the Treasury’s bank balance included <strong>{number(control_luna,6)} LUNA</strong>, alongside other denominations. This is a gross contract balance, not an available-spending budget, valuation or total Foundation asset figure. Reserved grant amounts, virtual Alliance tokens, staked positions and assets in other contracts must be reconciled separately.</p>
<h3>Could retained keys put Treasury funds at risk?</h3><p><strong>Yes: the upgrade layer creates a material route around ordinary in-contract approval rules.</strong> A compatible replacement implementation could change authorization, remove or weaken in-code veto checks, and instruct transfers of spendable assets held by the Treasury address. That is a consequence of administrator-controlled code replacement, not evidence that such a replacement or transfer has occurred. No live drain or destructive test was performed.</p><p>The same issue applies to assets held in other upgradeable contracts, including pooled user assets. Control over one contract does not automatically authorize withdrawals from every Foundation wallet or unrelated protocol. Staking, IBC, external contracts, liabilities and chain-level governance impose additional boundaries. The Board’s upgrade control of the hub and bridge is an important independent control, not a guarantee covering TLA or Treasury.</p>
<p class="note">The two ERIS-labelled addresses expose single public keys in their chain account records; neither is recorded as an on-chain multisig. That does not reveal who holds the keys, whether off-chain co-signing exists, or whether one individual can act alone. The launch attribution establishes ERIS-associated roles, not private key custody.</p>
{source_list([(CONTROL+'chain/treasury-contract.json','Treasury upgrade administrator and code ID'),(CONTROL+'chain/treasury-config.json','Treasury veto configuration'),(CONTROL+'chain/tla-registry-roles.json','Current role assignments'),(CONTROL+'chain/tla-dca-executors.json','DCA executor list'),(CONTROL+'chain/board-threshold.json','Board voting configuration'),(CONTROL+'chain/board-members.json','Four equal Board members'),(CONTROL+'chain/treasury-bank-balances.json','Gross bank balances'),(CONTROL+'chain/upgrade-admin-account.json','Upgrade-admin account type'),(CONTROL+'chain/registry-owner-account.json','Configuration-owner account type'),('https://github.com/CosmWasm/wasmd/blob/v0.54.10/x/wasm/keeper/keeper.go#L473-L576','Upstream Wasm migration authorization and replacement-code execution'),(TREASURY_TERMS,'Treasury launch functions and promised safeguards')])}</section>
<section id="inventory"><div class="section-heading"><h2>TLA/Treasury authority and related dependencies</h2><p>TLA and Treasury are the focus of this handover review. The broader 27-contract capture also retains application and ERIS-product records for context; inclusion does not establish community ownership or a duty to transfer those products.</p></div>{table(['System','Upgrade administration','Internal / operational authority'],[
['Treasury and TLA registry', 'ERIS upgrade address', 'ERIS configuration address owns the registry; Board holds PDT_CONTROLLER and several operational roles.'],
['TLA staking, connectors, asset gauge, bribes, voting escrow and zapper', 'ERIS upgrade address on all reviewed instances', 'Shared registry assigns Board whitelist, delegation, guardian and take-recipient roles; ERIS retains ownership above those role assignments.'],
['ampLUNA hub and CW20-ICS20 bridge', 'Phoenix Board after P9', 'Hub owner remains ERIS configuration address; bridge gov_contract remains ERIS upgrade address. The Board can approve further code changes.'],
['ampLUNA token', 'ERIS fixed multisig', 'Separate from the hub’s Board administrator. Token minter points to the hub. Do not treat the multisig as the same single-key account.'],
['vAMP escrow, proposal gauge and validator gauge', 'ERIS upgrade address', 'The reviewed gauge configurations retain the ERIS configuration owner; gauge voting and delegation roles are distinct from Board administration of the hub.'],
['arbLUNA token and arbitrage vault', 'ERIS upgrade address', 'Token minter identifies the separate vault; vault owner is the ERIS configuration address. The CW20 token is not itself the asset-management vault.'],
['Foundation operations DAO', 'Phoenix Board', 'A separate Foundation-controlled contract. This inventory does not establish all of its positions or every downstream dependency.']])}
{details('Broader inventory: 27 contracts, including application context', table(['Contract label','Address','Code','Administrator','Evidence'],control_rows,'Named contracts checked on 16 November 2026')+'<p>Of these 27 named contracts, 22 record the ERIS upgrade address, four record the Phoenix Board (including the Board DAO itself), and one records the ERIS fixed multisig. These counts describe this sample, not all Terra deployments or the value of assets owned.</p>', 'full-inventory')}
{source_list([(CONTROL+'chain/inventory.json','Complete captured inventory'),(CONTROL+'chain/manifest.json','Main acquisition times, URLs and hashes'),(CONTROL+'chain/supplement-manifest.json','Vault and gauge acquisition records'),(CONTROL+'chain/creda-registry-ownership.json','Creda registry ownership'),(CONTROL+'chain/creda-registry-roles.json','Creda roles'),(CONTROL+'chain/hub-config.json','Hub internal owner and settings'),(CONTROL+'chain/ics20-config.json','Bridge internal governance'),(CONTROL+'chain/arb-vault-config.json','Arbitrage vault configuration')])}</section>
<section id="approvals"><div class="section-heading"><h2>Infrastructure funding: TLA and Treasury</h2><p>These approvals fund tools to manage chain liquidity and community funds. The relevant comparison is between the approved operating safeguards and handover terms and what was delivered. Historical dollar descriptions are proposal values, not current valuations or proof of payment.</p></div>{details('Approved infrastructure funding and launch decisions',table(['Decision','Approved scope','Control / ownership boundary'],infrastructure_grants),'grant-record')}
<h3>What has been delivered against those terms?</h3>{table(['Commitment','Observed delivery at 16 November 2026','Assessment'],[
['TLA: deploy liquidity, voting and incentive infrastructure', 'Staking, connectors, voting escrow, gauges and bribe contracts are deployed. The launch links a published SCV audit.', 'Infrastructure delivered. This review does not certify every feature or subsequent upgrade.'],
['TLA: migration administration to Stewardship after one month', 'The reviewed TLA infrastructure contracts still name the ERIS upgrade address.', 'Handover remains incomplete.'],
['TLA: configuration ownership to Stewardship after three months', 'The shared registry still names the ERIS configuration owner, with no pending transfer.', 'Handover remains incomplete.'],
['TLA: Stewardship operating roles and community liquidity', 'The Board holds whitelist, delegation, guardian and take-recipient roles in the registry.', 'Meaningful operating authority assigned. Full take-rate accounting remains to be reconciled; registry ownership still sits above these roles.'],
['Treasury: deploy audited payment and funding tooling', 'The Treasury operates Board-approved payments and grants; a published SCV audit covers a stated source revision.', 'Tooling delivered. The audit has not been matched to an independently reproduced build of the current deployment.'],
['Treasury: Think Tank and governance spending safeguards', 'Configuration records the published three-day and ten-day delays and per-action / rolling thresholds; governance is veto owner.', 'Safeguards are configured. They have not been exhaustively execution-tested here and are not immutable against code replacement.'],
['Treasury: governance can stop funding and claw back locked funds', 'Native governance controls Alliance funding; the audited design includes clawback.', 'Funding-control route supported. Exact current clawback behavior needs validation before a recovery proposal.'],
['Published open-source access', 'The advertised contracts-ve3 repository returned 404 publicly on 16 November.', 'Access at the advertised location is unavailable. Relocation or Foundation private access was not established.']])}
<p><strong>TLA has an express missed handover; Treasury has a retained-control concern without the same explicit deadline.</strong> The Treasury administrator remains ERIS, and its configuration uses the same ERIS-owned registry. Do not apply TLA’s timetable to Treasury as though the Treasury terms independently state it.</p>
<p>The reviewed proposal texts and executed decisions are the agreement record used for this comparison. No additional terms or amendments are assumed. ERIS’s maintenance rationale is retained below; it does not itself document an approved timetable change.</p>
<h3>Rejected TLA changes are not adopted policy</h3><p>Whitelisting reform #4830 and pool relocation #4836 were rejected. Their proposed changes cannot be presented as new mandates, and rejection alone does not document repeal of the original handover commitments.</p>
<p class="note">This is a control and delivery comparison, not a full grant-performance audit. Quarterly reporting, the conditional URA refund, full take-rate accounting and all later source revisions require separate reconciliation.</p>
{source_list([(TLA_TERMS,'TLA launch: delivery, audit and handover terms'),(TREASURY_TERMS,'Treasury launch and safeguards'),(DOCS_PIN.replace('7cebbd26048f0e1568a2aed55177090b90788d8b','ee361d66c5f9e3603ba2efa55376914caed2eb95')+'2024-05-28_20123_terra-liquidity-alliance.md','TLA development and community-owned liquidity'),(CONTROL+'chain/inventory.json','Captured contract administrators'),(CONTROL+'chain/tla-registry-ownership.json','Registry owner and pending status'),(CONTROL+'chain/tla-registry-roles.json','Operating roles and take recipient'),(CONTROL+'chain/treasury-config.json','Configured Treasury veto safeguards'),(CONTROL+'approvals/native-4830.json','Rejected whitelisting reform'),(CONTROL+'approvals/native-4836.json','Rejected pool relocation')])}</section>
<section id="application-grants"><div class="section-heading"><h2>Separate category: grants to build applications</h2><p>Creda, Votion and Estima are application-development awards. Funding an application does not by itself assign the builder’s IP or require transfer of its administration. The executed funding messages contain no express IP assignment or TLA-style handover timetable. These awards are not evidence of failure to hand over TLA or Treasury.</p></div>{details('Application awards and payment boundaries',table(['Decision','Application award','Approval / payment boundary'],application_grants),'application-grant-record')}
<p>Beneficiary participation in payment approvals and verifiable milestone acceptance remain separate review questions. Other directors approved Estima’s original grant without a recorded 0xPhilipp vote. Creda A189 and Estima A258 were rejected drafts, not additional awards. Funding and milestone releases are not personal profit.</p><p><a href="/treasury/#project-funding">Application funding and delivery evidence</a> · <a href="/stakeholders/#creda-approval">Creda milestone-approval votes</a></p>
{details('Earlier ERIS protocol development grant: separate obligations',table(['Decision','Approved scope','Boundary'],legacy_grants)+'<p>The 2023 revised ERIS grant promises revenue sharing and progressive decentralization. Its budget includes four years of maintenance; its running-out-of-cash FAQ also describes open-source and Enterprise/Warp arrangements. Those obligations require their own reconciliation and do not establish a TLA-style deadline for every ERIS product. The original #3460 request was rejected before revised #3796 passed.</p>','earlier-eris-grant')}
{source_list([(DOCS_PIN.replace('7cebbd26048f0e1568a2aed55177090b90788d8b','ee361d66c5f9e3603ba2efa55376914caed2eb95')+'2023-01-02_8789_revised-eris-grant-proposal.md','Earlier ERIS grant: revenue sharing and maintenance'),(CONTROL+'approvals/board-A189.json','Rejected Creda draft'),(CONTROL+'approvals/board-A258.json','Rejected Estima draft')])}</section>
<section id="handover"><div class="section-heading"><h2>Promises, explanations and completed actions</h2></div>{table(['When','Evidence','What it establishes'],[
['August 2024',ext(TLA_TERMS+'#L144-L169','TLA launch terms'),'ERIS temporary admin/owner roles; migration-admin handover after one month and configuration-owner handover after three. These deadlines are TLA-specific.'],
['8 October 2024',ext('https://chainsco.pe/terra2/tx/B71CF351EB8A85620E18821288C35A4C73DD6B43B9751C08E937C8AC9FCEAF2F','Successful registry transaction'),'The ERIS configuration address assigned PDT_CONFIG_OWNER to itself. This shows actual use of registry authority; it does not establish the absence of off-chain authorization.'],
['1 October 2025',ext('https://chainsco.pe/terra2/tx/DC3118AA7A0A8BEC96AA7006074DF66A83321DEC0CEEDB2015B56AE83D80EB64','Successful registry transaction'),'The same address changed FEE_COLLECTOR. This is a specific role change, not proof that all Treasury funds or TLA fees were diverted.'],
['19 October 2026',ext('https://forum.phoenix.money/t/47/55','0xPhilipp’s response'),'ERIS retained TLA administration because it continued development, maintenance and operation, and considered transfer inappropriate given concerns about the Board. He welcomed supervisor review. This is the stated explanation; no approved timetable extension was identified in the reviewed records.'],
['25 October 2026',ext('https://chainsco.pe/terra2/tx/86E599263604B396BFB0F35F2F4E505E2EA758B024315B1C055C14994E6242D9','P9 execution'),'Two update_admin messages transferred hub and bridge upgrade authority to the Board. They did not transfer the hub internal owner, bridge gov_contract, Treasury administrator or TLA registry owner. P8 had been rejected.'],
['2 November 2026',ext('https://forum.phoenix.money/t/64/5','Vini’s response'),'Supports Stewardship administration, source and maintenance access, clear licensing and completing handover. Explicitly an individual view, not an agreed Board resolution.'],
['Confirmed 16 November 2026',control_link('handover/A292.json','A292 executed; 75 YES'),'The Board used its new hub authority to migrate to code 2726. The live hub still names the ERIS configuration owner. This was a Board-approved upgrade, not a unilateral ERIS replacement.']])}
<h3>The hub handover is real, but internal powers still matter</h3><p>The focused review of hub code 2726 found additional owner control over batching and unbonding timings, alongside existing fee, delegation and voting-operator settings. Poor settings could disrupt operation or delay withdrawals. The Board’s migration power provides a route to change these controls; the policy question is which settings the owner may change, under what limits and with whose approval.</p><p class="note">P9’s execution date comes from retained primary transaction evidence; executed proposal status and current administrators were checked again. A292 is now executed, superseding older discussion-stage descriptions. The focused binary review is not a full security audit.</p>
{source_list([(CONTROL+'handover/selected-responses.json','Scoped summaries and direct source posts'),(CONTROL+'handover/hub-history.json','Hub migration history'),('/#ampluna-control','Focused hub release and binary verification'),('/record/audit/eris_multisig/transactions.json','Retained P9 execution record'),('/record/audit/leads/transactions/terra2_B71CF351EB8A85620E18821288C35A4C73DD6B43B9751C08E937C8AC9FCEAF2F.json','Retained configuration-role transaction'),('/record/audit/leads/transactions/terra2_DC3118AA7A0A8BEC96AA7006074DF66A83321DEC0CEEDB2015B56AE83D80EB64.json','Retained fee-role transaction'),('https://github.com/erisprotocol/contracts-terra/blob/dbcaa4db951f2bec6e239ccf94f25c85f3bed80a/contracts/hub/src/execute.rs#L852-L911','Hub owner configuration source')])}</section>
<section id="risk"><div class="section-heading"><h2>Why this is a governance problem</h2></div><div class="two-col"><article><h3>Approval rules can sit below a stronger key</h3><p>Community voting and Board thresholds provide weaker assurance when another authority can replace the rules they rely on. That creates exposure to intentional misuse, key compromise and mistakes even if ordinary approvals are followed.</p></article><article><h3>Responsibility and power can diverge</h3><p>The Board is accountable for community assets but may depend on an outside operator for contract changes, source access or emergency recovery. A dispute or unavailable maintainer can interrupt service; an unclear handover makes that dependence difficult to assess.</p></article></div><p>The concern is structural. The evidence does not establish an intention to misuse funds, a completed theft, or legal ownership of all protocol assets by ERIS. ERIS’s maintenance rationale deserves consideration alongside the community’s right to explicit, reviewable limits on retained authority.</p>
<h3>Source access is part of control</h3><p>The Treasury launch advertised audited open-source code. The advertised <code>erisprotocol/contracts-ve3</code> public repository returned 404 when checked on 16 November. That does not establish whether it moved or whether the Foundation has private access. The September 2024 Treasury audit reviews a stated source revision; this review has not reproduced an exact-source build matching the current Treasury deployment. Publishing an audit alone does not resolve current upgrade custody or source-access questions.</p>
{source_list([('https://github.com/erisprotocol/contracts-ve3','Advertised source repository'),('https://github.com/SCV-Security/PublicReports/blob/main/Eris%20Protocol/Eris%20Protocol%20-%20Pheonix%20Treasury%20Contract%20-%20Audit%20Report%20v1.0.pdf','September 2024 Treasury audit'),(CONTROL+'handover/capture_manifest.json','Source-access check and acquisition history')])}</section>
<section id="governance-remedies"><div class="section-heading"><h2>Can Terra governance resolve these issues?</h2><p><strong>Yes. Native Terra governance can override the contract-administrator layer without the current administrator’s signature.</strong> Two public nodes report Terra v2.22.0, commit <code>e68dd029…</code>, using wasmd v0.54.10. The pinned Terra application assigns Wasm authority to the governance module and forwards administrator, migration and sudo messages to the reviewed handlers.</p></div><p>This is a separate route from a Phoenix Board proposal. It requires an executable Terra governance proposal that passes and executes successfully; a text-only vote does not change the contracts.</p>{table(['Mechanism','What it can fix','What it leaves unresolved'],[
['MsgUpdateAdmin', 'Reassign a named contract’s migration administrator to an approved DAO, multisig or governance address. The reviewed governance policy does not require consent from the existing ERIS administrator.', 'Internal owners, registry roles, fee recipients, executors and voting operators do not change merely because the chain-level administrator changes.'],
['MsgMigrateContract', 'Adopt reviewed replacement code. Its migration can repair internal ownership or role storage and retain the existing contract address and asset balances.', 'The exact code, storage compatibility and migration payload must be reviewed and tested. Claim records, liabilities, IBC callbacks and operating settings must survive as intended. This review has not prepared or simulated a recovery migration.'],
['MsgSudoContract', 'Invoke privileged operations actually implemented in a deployed contract’s sudo entrypoint.', 'It is not a universal command to rewrite ownership or storage. The current Treasury code 3347 and hub code 2726 have no sudo export. A direct sudo call cannot repair either current deployment. Other contracts need their own binary/schema checks.'],
['Ordinary MsgExecuteContract', 'Use powers the contract already grants the governance-module sender—for example supported governance veto or clawback operations.', 'It does not automatically impersonate the ERIS owner or bypass the contract’s ordinary authorization checks. Treasury clawback was advertised, but its exact current payload and behavior still need source/binary validation.'],
['Alliance funding changes', 'Change or stop the relevant reward funding through the chain’s Alliance governance mechanisms.', 'Stopping future inflows does not transfer administrators, recover already-paid funds or settle outstanding depositor and grant claims.']])}
<h3>For the Treasury and TLA, use a two-layer remedy</h3><p>A concrete recovery proposal could first specify the intended administrators for the Treasury, both registries and every affected dependent contract, then resolve internal owners and privileged roles through cooperative accepted transfers or reviewed migrations. Changing only the registry administrator would leave its current internal owner able to operate until that second layer is addressed. The hub and bridge already have Board migration administrators; their remaining internal permissions need separate treatment.</p><p><strong>Do not rely on sudo where the required entrypoint is absent.</strong> Inspection of the actual downloaded Treasury and hub bytecode found no <code>sudo</code> export; the byte hashes match the chain’s code metadata. This establishes an entrypoint limit, not a full behavioral audit. Governance can still authorize migration through the separate Wasm module handler.</p><p>The reviewed governance policy also permits administrator changes and migration when a contract has no administrator. Clearing an admin blocks the ordinary admin route, but does not remove this native governance recovery route.</p>
<h3>Recovery power is not immediate protection</h3><p>Existing keys can still act while a proposal is pending. Recheck deployed code and permissions before execution, test the complete proposal on a faithful fork, and specify post-execution checks for both administrators and internal roles. A proposal being accepted for voting does not prove its messages will execute successfully.</p><p>Governance cannot obtain missing private source or credentials merely by changing a contract field, settle legal/IP title, independently certify completed work, or automatically reverse assets already transferred beyond the affected contracts. A recovery proposal must preserve legitimate user claims and be accompanied by the source, maintenance and accountability work described below.</p>
{source_list([(CONTROL+'governance/verification.json','Live release evidence, code hashes and exported entrypoints'),('https://github.com/phoenix-directive/core/blob/e68dd029990a4cf347157f2426cabba4d9eb5c30/app/keepers/keepers.go#L477-L497','Terra’s Wasm governance authority'),('https://github.com/phoenix-directive/core/blob/e68dd029990a4cf347157f2426cabba4d9eb5c30/x/wasm/keeper/msg_server.go','Terra forwards migration, admin and sudo messages'),('https://github.com/CosmWasm/wasmd/blob/v0.54.10/x/wasm/keeper/authz_policy.go#L66','Governance authorization differs from ordinary admin authorization'),('https://github.com/CosmWasm/wasmd/blob/v0.54.10/x/wasm/keeper/msg_server.go#L420','Governance-policy selection'),('https://github.com/CosmWasm/wasmd/blob/v0.54.10/x/wasm/keeper/msg_server.go#L286','Sudo invokes the deployed entrypoint'),('https://github.com/phoenix-directive/cosmos-sdk/blob/v0.50.15-terra.0/x/gov/keeper/proposal.go#L41-L86','Proposal signer validation and execution limits')])}</section>
<section id="next"><div class="section-heading"><h2>What a complete handover should demonstrate</h2></div><ol><li><strong>An asset and authority register:</strong> each contract, asset claim, funding source, legal owner where established, migration admin, internal owner, operator, fee recipient and downstream dependency.</li><li><strong>An approval trail:</strong> the grant or ruling authorizing each retained power, applicable deadline, approved variation and any outstanding revenue-sharing or source-delivery obligation.</li><li><strong>Verified transfers:</strong> executed transactions and accepted ownership, followed by fresh queries of every layer. A new spending controller alone does not prove the upgrade or registry owner changed.</li><li><strong>Operational continuity:</strong> reproducible deployed builds, licences, source/documentation access, key recovery, maintenance and tested emergency procedures.</li><li><strong>Independent limits:</strong> disclosed conflicts, independent approval of upgrades and related-party payments, appropriate delay/monitoring controls, and a published route for urgent action.</li></ol><p>These are proposed verification requirements, not claims that governance has already enacted them. The two current discussion proposals can use this register to define what must transfer, what may remain with an operator, and which community assets need protection during transition.</p>{nextlinks(('/treasury/','Treasury payments and funding'),('/governance/','Proposals and governance reforms '+ARROW))}</section>
</div>'''
page('TLA and Treasury funding, safeguards and retained control',control,'/control/','TLA and Treasury infrastructure terms, delivered safeguards and incomplete handovers. Application-development grants are a separate category. Checked 16 November 2026.')

# Governance findings, verified handover and longer-term reforms.
governance = head('Board rules and contract control', 'The board received upgrade control over two contracts, but several internal permissions remained unchanged. The records below separate those powers and examine the board’s approval and veto rules.') + f'''<div class="wrap page-content"><section id="board-approvals"><div class="section-heading"><h2>Board approval rules</h2></div><p>The four-seat board requires three YES votes. That means any three can approve an action over the fourth seat’s objection or absence. A159, A249 and A271 show why beneficiary disclosure and recusal matter across the whole board.</p><p>A272 proposed removing Vini and reducing the threshold to 60%. It failed: 0xPhilipp and MB voted YES, Rose voted NO and Vini was absent. The current captured board remains four seats at 75%. Sequence alone does not establish motive.</p></section>
<section><div class="section-heading"><h2>The Think Tank cast no YES or NO votes on four veto proposals</h2></div><p>Four substantive veto proposals had zero YES and zero NO ballots. Only limited abstentions were recorded. The technical member proposed all five and abstained on all five. P5’s empty message means the proposed veto could not execute even if approved.</p><p>The records leave two problems to resolve: missing votes and an empty veto message. Membership history, notifications and proposal construction need checking; the reasons for non-participation are unknown.</p></section>
<section id="handover"><div class="section-heading"><h2>“Update admin” is not the same as “transfer ownership”</h2><p>The board received upgrade control over two contracts on 25 October 2026. The historical captures below record unchanged internal settings. The <a href="/control/#handover">16 November review</a> checks those roles again and records the subsequent A292 upgrade.</p></div>{table(['Contract / role', 'After ERIS proposal 9', 'Still retained elsewhere'], [['ampLUNA hub CosmWasm admin', 'Phoenix board <code>terra1k8ug…lppjg</code>', '—'], ['ampLUNA hub <code>config.owner</code>', 'Unchanged', '<code>terra1kefa…klgzl</code>; <code>new_owner: null</code>'], ['CW20-ICS20 CosmWasm admin', 'Phoenix board <code>terra1k8ug…lppjg</code>', '—'], ['CW20-ICS20 <code>gov_contract</code>', 'Unchanged', '<code>terra1q0v…tew</code>'], ['Treasury and TLA registry migration admin', 'Not changed by proposal 9', '<code>terra1q0v…tew</code>'], ['TLA registry configuration owner', 'Not changed by proposal 9', '<code>terra1kefa…klgzl</code>; no pending owner']])}<p>Proposal 9 contains exactly two <code>wasm.update_admin</code> messages. Calling it “Transfer Ownership” is therefore incomplete: it transferred code-upgrade control, not all operational/configuration control.</p>{source_list([('https://chainsco.pe/terra2/tx/86E599263604B396BFB0F35F2F4E505E2EA758B024315B1C055C14994E6242D9', 'Proposal 9 execution transaction'), (LCD + '/cosmwasm/wasm/v1/contract/terra10788fkzah89xrdm27zkj5yvhj9x3494lxawzm5qq3vvxcqz2yzaqyd3enk/smart/eyJjb25maWciOnt9fQ==', 'Current hub internal config'), (LCD + '/cosmwasm/wasm/v1/contract/terra1e0mrzy8077druuu42vs0hu7ugguade0cj65dgtauyaw4gsl4kv0qtdf2au/smart/eyJjb25maWciOnt9fQ==', 'Current ICS20 internal config'), ('/record/audit/admin_handover/', 'Download the contract metadata and config captures')])}<h3>Original handover commitments</h3><p>The 2024 TLA launch text says registry ownership transfers after three months and contract admin after one month. The packaged ledger identifies 31 privileged operations in 19 transactions after its conservative cutoff, affecting seven original contracts. The original commitment and roles were independently checked at the October capture; every historical ledger operation was not replayed in this review.</p><p class="note">Successful transactions prove use of an address’s authority, not exclusive human key custody. No approved extension was found in the reviewed records; an agreement elsewhere remains possible.</p></section>
<section id="reforms"><div class="section-heading"><h2>Longer-term reforms</h2></div><div class="reform-grid"><article><h3>Disclose and recuse</h3><p>Maintain a current stakeholder register covering grants, compensation, OTC, hosting, delegations and voting power. Require recusal and independent approval for related-party decisions, with the rationale published.</p></article><article><h3>Make veto proposals usable</h3><p>Give the Think Tank reliable notifications, complete executable messages, adequate voting windows and published rationales. Publish participation records and investigate failed veto proposals.</p></article><article><h3>Separate technical powers</h3><p>Document migration admin, internal owner, treasury control and vote operator separately. Use explicit acceptance for ownership transfers, independent verification and runbooks for emergency action.</p></article><article><h3>Publish voting instructions and results</h3><p>Publish hub/gauge intentions and final ballots, validator-mandate rules and material voting-power holders at entity level. Preserve weighted dissent and avoid interpreting delegation as ownership.</p></article><article><h3>Record each payment’s approval and acceptance</h3><p>Keep the budget, recipient, declared conflicts, promised work, acceptance, entitlement, claim and valuation together. Independently reconcile recurring expenses and related-party OTC execution.</p></article><article><h3>Review and respond</h3><p>Commission periodic independent control review with access to off-chain agreements. Give affected stakeholders a right of response and publish corrections against specific evidence.</p></article></div>{source_list([('https://www.oecd.org/en/publications/g20-oecd-principles-of-corporate-governance-2023_ed750b30-en/full-report/component-8.html', 'G20/OECD Principles: board responsibilities'), ('https://legalinstruments.oecd.org/public/doc/151/body-text.en.html', 'OECD disclosure principles'), ('https://www.oecd.org/en/publications/2005/08/managing-conflict-of-interest-in-the-public-sector_g1gh5807.html', 'OECD conflict-of-interest toolkit'), ('https://www.iso.org/standard/65036.html', 'ISO 37000:2021 governance of organizations'), ('https://controlsframework.net/icif/index.php', 'COSO Internal Control—Integrated Framework'), ('https://aisel.aisnet.org/jais/vol19/iss10/1/', 'Beck et al.: blockchain governance research'), ('https://arxiv.org/abs/2302.12125', 'Hidden Shortcomings of DAOs'), ('https://www.tandfonline.com/doi/full/10.1080/25741292.2023.2270220', 'Research on DAO governance impacts')])}</section>{nextlinks(('/treasury/', 'Back: treasury'), ('/evidence/', 'Next: evidence and method ' + ARROW))}</div>'''
rebalance = supplement['ceres_removal_rebalance']['facts']
authority_update = f'''<section id="allocation-use"><div class="section-heading"><h2>Ceres removal and redelegation</h2></div><ol class="timeline"><li><time datetime="2026-10-09T03:09:55Z">9 Oct · 03:09:55 UTC</time><div><h3>Ceres removed from the hub whitelist</h3><p>The published ERIS configuration address executed the removal.</p></div></li><li><time datetime="2026-10-09T03:10:35Z">9 Oct · 03:10:35 UTC</time><div><h3>Rebalance 40 seconds later</h3><p>Seven redelegations totalled {number(rebalance['total_LUNA'], 6)} LUNA, including {number(rebalance['from_removed_validator_LUNA'], 6)} LUNA away from Ceres.</p></div></li></ol><p>Compare the eligibility criteria, whitelist, gauge outputs and public rationale immediately before and after the change. These hub staking redelegations are distinct from Phoenix Alliance allocations. Timing alone does not establish retaliation, favoritism or coordinated voting.</p>{source_list([('https://chainsco.pe/terra2/tx/536298700377664639E3CF27AD0FED8495946C3F835FCEC64B02C97F6E15BA88', 'Removal transaction'), ('https://chainsco.pe/terra2/tx/42CF090DCD271A49A26E6679C9BA4597D47342C9603929D79F973D2AC12CE776', 'Rebalance transaction'), (LEADS + 'redelegations.json', 'All seven redelegations with event references')])}</section>
<section id="retained-roles"><div class="section-heading"><h2>Other retained permissions</h2></div><p>The 27 October queries show the published ERIS configuration address as hub and prop-gauge owner, while the hub’s raw vote operator points to the prop-gauge. Creda’s registry identifies the protocol fee account as reserve controller; the Portfolio’s migration administrator is a separate role.</p><p>The successful FEE_COLLECTOR assignment, Treasury configuration-role assignment and arbLUNA collateral addition also document uses of retained authority. These records show assigned permissions and asset movements; they do not establish personal profit. Two Creda reserve collections included 5,701.254836 and 2,679.750683 LUNA, alongside other assets that remain separately denominated.</p><p class="note">These current responses do not establish the requested historical snapshots: providers did not return headers confirming those heights. Match permissions to deployed code before asserting every supported capability, and do not infer exclusive personal key custody from a public role label.</p>{source_list([(LEADS + 'verified_findings.json', 'Authority events, current roles and reserve collections'), (LEADS + 'queries/hub_vote_operator_current.json', 'Raw hub vote-operator response'), (LEADS + 'queries/creda_roles_current.json', 'Creda reserve-controller roles')])}</section>
<section id="source-response"><div class="section-heading"><h2>Why ERIS says it made source code private</h2></div><p>ERIS’s retrospective says appropriate contracts were moved to private source for security. That is ERIS’s explanation for the missing public source.</p><p>The stated rationale does not independently establish stronger security or audit coverage for every deployed 2026 revision. Public audit reports exist; independent review still needs the auditor, scope, source commit, deployed checksum, outstanding findings and remediation.</p>{source_list([(YEAR_ARTICLE, 'ERIS explanation and security claims'), ('https://github.com/SCV-Security/PublicReports/tree/main/Eris%20Protocol', 'Published ERIS audit reports'), (LEADS + 'verified_findings.json', 'Scope of the transaction checks')])}</section>'''
governance = governance.replace('<section id="reforms">', authority_update + '<section id="reforms">', 1)
proposal_governance = f'''<section class="reading" id="proposed-amendments"><h2>16 November: two independent proposals</h2><p>Proposal 1 seeks 0xPhilipp’s removal and a controlled transition. Proposal 2 establishes community governance and independent accountability and can operate with the existing Board if Proposal 1 fails. These are discussion texts. Each requires its own passage and lawful adoption under the existing governing documents.</p>
<h3>Three approvals through the transition</h3><p><strong>All directors must approve until a fourth director is appointed, after which three approvals are required.</strong> Proposal 1 therefore requires 3-of-3, then 3-of-4 and 3-of-5. It removes the earlier temporary 2-of-3 permission. Recusal, abstention or an old proposal snapshot must not reduce the affirmative-approval minimum. Proposal 2 grants no two-approval permission.</p><p>The ongoing 4855 election continues; the replacement seat has a separate election. If removal leaves four directors, three approvals are required. Discretionary interim authority expires 60 calendar days after activation or when the fourth joins, whichever is earlier. Limited caretaker acts after day 60 still require all three remaining directors; expiry does not relax the approval rule.</p>
<h3>Implementation and independent review</h3><p>Each proposal calls for acknowledgement and named implementers within seven calendar days of passage, an implementation dossier within 21 calendar days of passage, weekly progress and prompt disclosure of material obstacles. Late acknowledgement does not restart the 21-day clock. The dossier must identify legal authority, required approvals, funding, independent appointments, contract-control records and a dated remedy for every missing item.</p><p>Proposal 2’s independent financial and authority review covers Foundation-controlled funds and powers and relevant TLA commitments from 12 August 2024 through passage, with bounded earlier and later records where needed. It examines relevant decisions by every director, reconciles paid and conditional amounts without double counting, and tests milestone acceptance and privileged operations. Subjects may respond but cannot control reviewer selection, findings, publication or fees.</p><p>Preliminary findings are due within 30 calendar days and a final report within 60 calendar days of legal adoption. Affected parties have at least seven calendar days to respond to proposed adverse findings. Missing funding, access or appointments must be disclosed and pursued; a status report is not an independent review. Neither removal nor an evidence gap establishes liability.</p>
<h3>Continuing public accountability</h3><ul><li>A public decision register, updated within seven calendar days of decisions or material changes, subject to earlier duties.</li><li>Accountability reports every four calendar months from adoption, alongside weekly implementation updates.</li><li>A proposed Board/community approval framework within 60 calendar days of adoption, at least 21 calendar days for public comment, and submission of the exact framework to Terra Governance within 90 calendar days of adoption.</li></ul><p>The framework must consider related financial exposure, purpose, risk, conflicts and control. Preparing it grants no new spending power. Conflict rules prohibit beneficiaries from approving their own project budgets, milestone acceptance or payment releases; an approval impasse needs a lawful remedy, not fewer signatures.</p>
<h3>Verify handover and operating readiness</h3><p>Both proposals preserve the original administration-after-one-month and ownership-after-three-month commitments. The 21-day dossier must cover direct and indirect privileged control, TLA global configuration, Foundation-used Treasury/v3 contracts, source/build/licence and maintenance access, independent operating checks and a costed contingency plan. Completed transfers receive credit; unresolved scope and access remain identified as such. These requirements do not establish current ownership or prove a failure before the evidence is reviewed.</p><p>Community passage, legal adoption and contract execution remain distinct. Required legal and technical safeguards continue. Specific obstacles require assessment and a lawful remedy while unaffected work proceeds. Neither proposal authorizes unspecified expenditure, automatic asset recovery, an automatic shutdown or a transfer of unrelated ERIS property.</p>{source_list([(PROPOSAL_1, 'Proposal 1 and exact transition amendment — 16 November revision'), (PROPOSAL_2, 'Proposal 2 and exact governance amendments — 16 November revision'), (PROPOSALS_URL, 'Latest discussion texts'), (REFORM_FORUM, 'Original forum discussion'), ('/#proposal-reasoning', 'Reasoning, responses and evidence limits')])}</section>'''
governance = governance.replace('<section id="board-approvals">', proposal_governance + '<section id="board-approvals">', 1)
governance = insert_before_reading(governance, '<section><h2>TLA and Treasury: funding to manage community assets</h2><p>The <a href="/control/">16 November control review</a> compares the terms for chain liquidity and Treasury infrastructure with delivered safeguards, retained authority and outstanding handovers. <a href="/control/#application-grants">Application-development grants</a> are a separate category; their funding does not itself require transfer of the builder’s IP or establish a TLA-style handover obligation.</p></section>')
page('Governance and independent controls', governance, '/governance/')

# Evidence, provenance and correction boundaries.
evidence = head('Evidence and method', 'Voting histories, transaction responses, calculations and verification limits.') + f'''<div class="wrap page-content"><section><div class="section-heading"><h2>Voting-history downloads</h2></div>{table(['Dataset', 'Coverage', 'Download'], [['Phoenix board', 'A1–A289; all four directors', local('/record/audit/phoenix_board_votes_all.csv', 'CSV') + ' · ' + local('/record/audit/mb_voting_record.json', 'compiled record with per-ballot source locators')], ['Phoenix board, recent', 'A269–A289; last-four-weeks review window', local('/record/audit/phoenix_board_votes_last4weeks.csv', 'CSV')], ['ERIS fixed multisig', 'P1–P9; all five current voters', local('/record/audit/eris_multisig_votes_all.csv', 'CSV') + ' · ' + local('/record/audit/eris_multisig/proposals.json', 'proposal JSON')], ['Think Tank', 'P1–P5; all six current members', local('/record/audit/thinktank/votes.csv', 'CSV') + ' · ' + local('/record/audit/thinktank/proposals.json', 'proposal JSON')], ['Native 4853', str(refresh['ballot_count']) + ' current ballots; ' + CAPTURE_LABEL, local(REFRESH + 'votes.csv', 'CSV') + ' · ' + local(REFRESH + 'tally.json', 'tally JSON')], ['Lion DAO A33', 'Relationship, voting-power and timing analysis', local('/record/audit/lion_dao/ryan_relationship.json', 'JSON')]])}<p class="note">“All” means all records in the identified proposal range or capture—not every historical transaction on Terra. Current chain state can change after the snapshot. The <a href="/record/audit/native_4853_votes_all.csv">earlier 83-ballot native export</a> remains available for comparison.</p></section>
<section><div class="section-heading"><h2>Evidence labels</h2></div><dl class="definitions"><dt>Confirmed record</dt><dd>A direct chain response, transaction, contract state, source-code line or dated primary document. A successful action proves use of authority, not exclusive key custody.</dd><dd></dd><dt>Derived analysis</dt><dd>Arithmetic, grouping or comparison of cited records. The full-hub-YES outcome and combined vAMP shares are scenarios, not observed events.</dd><dt>Interpretation</dt><dd>A relationship or pattern that justifies a question. Timing, payments, shared protocols and NFT collections alone do not establish ownership, coordination or motive.</dd><dt>Unresolved</dt><dd>Missing off-chain agreements, classification, historical membership or notification evidence. A search of these records cannot establish that no other evidence exists.</dd></dl></section>
<section><div class="section-heading"><h2>Original records behind the supplied website</h2></div><p>The initial packet came from <a href="https://philipp-payments.pages.dev/">philipp-payments.pages.dev</a>. Its source index and embedded locators were used to identify original chain, forum and GitHub records where possible. Preserved source copies remain under <a href="/record/">/record/</a>; their original commentary is not adopted as this review’s conclusion.</p><ul><li>The compiled A1–A289 record retains per-proposal ballot query URLs, transaction hashes and source hashes.</li><li>The packaged authority ledger retains operation-level transaction locators. The original handover lines and current roles were checked separately.</li><li>Every retained data artifact has a sibling <code>.source.md</code> describing immediate source, upstream source where established, transformation and SHA-256.</li><li>The supplied uncorroborated spreadsheet is not published or used as an attribution source.</li></ul>{source_list([('https://github.com/PFC-Validator/phoenix-forensics', 'Audit repository and provenance register'), ('https://github.com/phoenix-directive/docs', 'Phoenix Directive original governance documents'), ('https://github.com/erisprotocol/contracts-tokenfactory', 'ERIS contracts and voting source'), ('https://forum.phoenix.money/', 'Phoenix governance forum'), ('https://phoenix.money/', 'Phoenix project website')])}</section>
<section><div class="section-heading"><h2>Scope and limitations</h2></div><ul><li>Historical governance review cutoff: 26 October 2026; native tally and scenario refreshed {CAPTURE_LABEL}. Proposal 4853 was rejected on 31 October; these are preserved pre-close snapshots.</li><li>Source independence: the current refresh uses the HighStakes LCD, operated by a reviewed validator. Its identified operator has an ABSTAIN ballot and approximately 3.254M LUNA of hub delegation. The earlier 27 October refresh used tdrsys; that endpoint did not complete a TLS connection for this refresh. Sequential queries do not establish a common block height. Earlier hub and ICS20 configuration captures were exactly cross-checked against tdrsys; the fresh tally has not been independently cross-checked.</li><li>Smart Stake validator-total weights are secondary analytics. Primary native ballots contain options, not per-ballot LUNA weights.</li><li>Not every packaged historical operation was independently replayed; that limitation is stated wherever the ledger is used.</li><li>Some providers omit older records or do not index all transactions. An empty search result cannot establish that an action never occurred.</li><li>Payment coverage and historical valuation vary by category. Gross flows are not net worth, profit or loss.</li><li>No identity research, surname-based searches or personal-contact calls are part of this review.</li></ul></section>
<section><div class="section-heading"><h2>Corrections and responses</h2></div><p>Corrections should identify the page, statement and supporting source. Responses and corrections should appear beside the affected claim.</p><button class="button secondary" data-share>Copy this page’s link</button><p class="share-status" role="status" aria-live="polite"></p></section>{nextlinks(('/governance/', 'Back: governance reforms'), ('/', 'Return to overview ' + ARROW))}</div>'''
evidence_update = f'''<section id="transaction-supplement"><div class="section-heading"><h2>27 October transaction supplement</h2><p>48 successful primary transaction records, with explicit limits on what each proves.</p></div><p>For all 38 Terra transactions, SHA-256 recomputed from the original encoded transaction bytes matches the cited hash; RPC height and execution code also match the LCD response. The archive endpoints may share infrastructure. This is a byte/hash and execution consistency check, not independent consensus or inclusion-proof verification.</p><p>The supplement contains 466 transfer rows, eight funded voting locks, seven redelegations and 23 findings with stated verification limits. Native transfers, CW20 and ERC20 movements retain their units. Fee-share events annotate bank transfers rather than adding the same receipt again; eight empty-amount transfer events remain explicitly unquantified.</p>{table(['Evidence', 'Download', 'Boundary'], [['Findings and lead status', local(LEADS + 'verified_findings.json', 'Findings') + ' · ' + local(LEADS + 'lead_status.json', 'Status by lead'), 'A supported finding may verify only part of a lead'], ['Transfers', local(LEADS + 'transfers.csv', 'CSV') + ' · ' + local(LEADS + 'transfers.json', 'JSON'), 'Movements are not automatically income'], ['Funding and current Creda positions', local(LEADS + 'year_review_analysis.json', 'Calculations'), 'External Votion payment is funder-reported; position shares are approximate'], ['Primary captures and failed attempts', local(LEADS + 'capture_manifest.json', 'Transaction manifest') + ' · ' + local(LEADS + 'query_manifest.json', 'Query manifest'), 'Six cited transactions remain unavailable; absence is not established'], ['Original-byte consistency checks', local(LEADS + 'rpc_manifest.json', 'RPC manifest'), 'No independent consensus verification asserted']])}<p>Fourteen requested historical state queries lacked response headers confirming the requested heights. Separate current captures do not replace them. Full cumulative fee histories, lock changes, historical validator eligibility and cross-chain message/nonce reconciliation remain open.</p><p class="note">The native tally and YES scenario were updated at {CAPTURE_LABEL}; earlier voting records are retained separately. This review does not independently audit every transaction.</p>{source_list([(LEADS, 'Browse supplemental datasets'), (LEADS + 'year_review_analysis.json.source.md', 'Funding-analysis provenance'), (YEAR_ARTICLE, 'ERIS retrospective and stated response')])}</section>'''
